import sys

def apply_move(a, d, s):
    a_list = list(a)
    a_list[d-1] = str(int(a_list[d-1]) + s)
    a_list[d] = str(int(a_list[d]) + s)
    return ''.join(a_list)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = input[1]
    b = input[2]

    if a == b:
        print(0)
        return

    moves = []
    for i in range(n-1):
        diff = int(b[i]) - int(a[i])
        if diff == 0:
            continue
        elif diff == 1:
            moves.append((i+1, 1))
        elif diff == -1:
            moves.append((i+1, -1))
        else:
            print(-1)
            return

    current = a
    for d, s in moves:
        current = apply_move(current, d, s)

    if current != b:
        print(-1)
        return

    print(len(moves))
    for move in moves[:10**5]:
        print(move[0], move[1])

main()
